parameters.jsCode:
/**
 * Normalizes one Gmail message into the canonical Join email-request payload.
 * @param {Object} $json Raw Gmail Trigger item supplied by n8n.
 * @returns {{json: Object}} Normalized request metadata and a Triage task draft.
 * @throws {Error} When required sender or message data is missing.
 */
const raw = $json || {};

function getAddressRecord(value) {
  if (!value || typeof value !== 'object') return null;
  const records = Array.isArray(value.value) ? value.value : [];
  return records.find((record) => record && record.address) || null;
}

function getAddressText(value) {
  if (value && typeof value === 'object') return String(value.text || '').trim();
  return String(value || '').trim();
}

function extractEmail(value) {
  const record = getAddressRecord(value);
  if (record) return String(record.address || '').trim().toLowerCase();
  const text = getAddressText(value);
  const angleMatch = text.match(/<([^<>\s]+@[^<>\s]+)>/);
  if (angleMatch) return angleMatch[1].toLowerCase();
  const bareMatch = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
  return bareMatch ? bareMatch[0].toLowerCase() : '';
}

function extractName(value, email) {
  const record = getAddressRecord(value);
  if (record && record.name) return String(record.name).trim();
  const text = getAddressText(value);
  const beforeAddress = text.includes('<') ? text.slice(0, text.indexOf('<')) : '';
  const normalized = beforeAddress.replace(/^['\"]|['\"]$/g, '').trim();
  return normalized || (email ? email.split('@')[0] : 'External stakeholder');
}

function htmlToText(value) {
  return String(value || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/\s+/g, ' ')
    .trim();
}

const senderEmail = extractEmail(raw.from);
if (!senderEmail) throw new Error('The incoming message has no valid sender email.');

const senderName = extractName(raw.from, senderEmail);
const rawSubject = String(raw.subject || '').replace(/\s+/g, ' ').trim();
const subject = rawSubject.replace(/^\[JOIN REQUEST\]\s*/i, '').trim();
const rawBody = String(raw.text || '').trim() || htmlToText(raw.html || raw.textAsHtml || raw.snippet);
const body = rawBody
  .replace(/\n*Gesendet mit der Telekom Mail App\s*\n*<?https?:\/\/www\.t-online\.de\/service\/redir\/emailmobilapp_[^>\s]*>?\s*$/i, '')
  .trim();
if (!subject && !body) throw new Error('The incoming message contains neither a subject nor a body.');

const receivedAt = raw.date ? new Date(raw.date) : new Date();
const safeReceivedAt = Number.isNaN(receivedAt.getTime()) ? new Date() : receivedAt;
const temporaryDueDate = new Date(safeReceivedAt.getTime() + 7 * 24 * 60 * 60 * 1000)
  .toISOString()
  .slice(0, 10);
const gmailMessageId = String(raw.id || '').trim();
if (!gmailMessageId) throw new Error('The Gmail message ID is missing.');

return {
  json: {
    gmailMessageId,
    gmailThreadId: String(raw.threadId || '').trim(),
    sourceMessageId: String(raw.messageId || gmailMessageId).trim(),
    requestDate: safeReceivedAt.toLocaleDateString('en-CA', { timeZone: 'Europe/Berlin' }),
    task: {
      title: (subject || 'Email request').slice(0, 120),
      description: (body || 'No email body provided.').slice(0, 4000),
      dueDate: temporaryDueDate,
      category: 'user',
      priority: 'medium',
      status: 'triage',
      creator: {
        type: 'external',
        source: 'email',
        name: senderName,
        email: senderEmail
      },
      aiGenerated: false,
      subtasks: [],
      assigned: [],
      sourceMessageId: String(raw.messageId || gmailMessageId).trim(),
      gmailMessageId,
      createdAt: safeReceivedAt.toISOString(),
      processingVersion: 'mvp-1'
    }
  }
};

