parameters.jsCode:
/**
 * Validates Gemini's structured analysis and merges it into the normalized task.
 * @returns {{json: Object}} Canonical AI-generated task and source-message metadata.
 * @throws {Error} When Gemini output, category, priority or deadline is invalid.
 */
const normalized = $('Normalize Email').item.json;
const baseTask = normalized.task;
const parts = Array.isArray($json.content?.parts) ? $json.content.parts : [];
const outputText = parts
  .filter((part) => part && typeof part.text === 'string')
  .map((part) => part.text)
  .join('')
  .trim();

if (!outputText) throw new Error('Gemini returned no structured task analysis.');

let analysis;
try {
  const jsonText = outputText
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '')
    .trim();
  analysis = JSON.parse(jsonText);
} catch (error) {
  throw new Error('Gemini task analysis is not valid JSON.');
}

const title = String(analysis.title || '').replace(/\s+/g, ' ').trim().slice(0, 120);
if (!title) throw new Error('Gemini returned an empty task title.');

const allowedCategories = new Set(['tech', 'user']);
if (!allowedCategories.has(analysis.category)) {
  throw new Error(`Unsupported AI category: ${analysis.category}`);
}

const allowedPriorities = new Set(['urgent', 'medium', 'low']);
if (!allowedPriorities.has(analysis.priority)) {
  throw new Error(`Unsupported AI priority: ${analysis.priority}`);
}

const rawSubtasks = Array.isArray(analysis.subtasks) ? analysis.subtasks : [];
const seenSubtasks = new Set();
const subtasks = [];

for (const item of rawSubtasks) {
  const rawTitle = typeof item === 'string' ? item : item?.title;
  const subtaskTitle = String(rawTitle || '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 120);
  const dedupeKey = subtaskTitle.toLowerCase();
  if (!subtaskTitle || seenSubtasks.has(dedupeKey)) continue;
  seenSubtasks.add(dedupeKey);
  subtasks.push({ title: subtaskTitle, done: false });
  if (subtasks.length === 10) break;
}

function isIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(value || ''))) return false;
  const date = new Date(`${value}T00:00:00.000Z`);
  return !Number.isNaN(date.getTime()) && date.toISOString().slice(0, 10) === value;
}

const requestDate = normalized.requestDate;
const fallbackDueDate = new Date(`${requestDate}T12:00:00.000Z`);
fallbackDueDate.setUTCDate(fallbackDueDate.getUTCDate() + 7);
let dueDate = fallbackDueDate.toISOString().slice(0, 10);
if (analysis.dueDate !== null) {
  if (!isIsoDate(analysis.dueDate)) throw new Error('Gemini returned an invalid due date.');
  if (analysis.dueDate < requestDate) throw new Error('Gemini returned a due date before the email was received.');
  dueDate = analysis.dueDate;
}

const description = String(baseTask.description || 'No email body provided.').trim().slice(0, 4000);

return {
  json: {
    ...normalized,
    task: {
      ...baseTask,
      title,
      description,
      dueDate,
      category: analysis.category,
      priority: analysis.priority,
      subtasks,
      status: 'triage',
      aiGenerated: true,
      processingVersion: 'gemini-1'
    }
  }
};

/**
 * Prepends the required AI-generation marker to the stored task description.
 * @param {Object} $json Validated task payload supplied by n8n.
 * @returns {{json: Object}} Payload with exactly one AI-generation marker.
 */
const data = $json || {};
const task = data.task || {};
const marker = '[AI-generated ticket from email]';
const originalDescription = String(task.description || 'No email body provided.')
  .replace(/^\[AI-generated ticket from email\]\s*/i, '')
  .trim();

return {
  json: {
    ...data,
    task: {
      ...task,
      description: `${marker}\n\n${originalDescription}`.slice(0, 4000)
    }
  }
};

